using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using System.Security.Claims;

namespace Identity.Controllers
{
    [Authorize]
    public class ClaimsController : Controller
    {
        public ViewResult Index()
            => View(User?.Claims);
    }
}

@model IEnumerable<Claim>
@{
    ViewData["Title"] = "Your Claims";
}
<h2 class="bg-primary m-1 p-1 text-white">Claims</h2>
<table class="table table-sm table-bordered">
    <tr>
        <th>Type</th>
        <th>Value</th>
        <th>Issuer</th>
    </tr>
    @foreach (var claim in Model.OrderBy(c => c.Type))
    {
        <tr>
            <td>@claim.Type</td>
            <td>@claim.Value</td>
            <td>@claim.Issuer</td>
        </tr>
    }
</table>

public class ClaimsController : Controller
{
    private readonly UserManager<AppUser> userManager;

    public ClaimsController(UserManager<AppUser> userMgr)
    {
        userManager = userMgr;
    }

    public ViewResult Index() => View(User?.Claims);
    public ViewResult Create() => View();

    [HttpPost]
    [ActionName("Create")]
    public async Task<IActionResult> Create_Post(
        string claimType, string claimValue)
    {
        AppUser user = await userManager.GetUserAsync(HttpContext.User);

        var claim = new Claim(
            claimType, claimValue, ClaimValueTypes.String);

        IdentityResult result =
            await userManager.AddClaimAsync(user, claim);

        if (result.Succeeded)
            return RedirectToAction("Index");

        foreach (var error in result.Errors)
            ModelState.AddModelError("", error.Description);

        return View();
    }

    [HttpPost]
    public async Task<IActionResult> Delete(string claimValues)
    {
        AppUser user = await userManager.GetUserAsync(HttpContext.User);
        string[] parts = claimValues.Split(';');

        var claim = User.Claims.FirstOrDefault(c =>
            c.Type   == parts[0] &&
            c.Value  == parts[1] &&
            c.Issuer == parts[2]);

        if (claim != null)
        {
            IdentityResult result =
                await userManager.RemoveClaimAsync(user, claim);

            if (result.Succeeded)
                return RedirectToAction("Index");
        }
        return View("Index");
    }
}
